    se.assign(4 * n, -1);
    cm.assign(4 * n, 0);
    sm.assign(4 * n, 0);
    build(1, 0, (int)n - 1, a);
    string out;
    for (long long k = 0; k < q; k++) {
        long long kind = ops[k][0], l = ops[k][1], rr = ops[k][2], x = ops[k][3];
